\begin{theorem}\label{thm:main}
Let
$n\geq2$, $0<\gamma\leq 1/4$, $0<\varepsilon\leq 1$, and
$0<\delta,\beta<1/10$.  There is an $(\varepsilon, \delta)$ edge-DP algorithm that, on every
nonnegative weighted $n$-vertex graph $G$, runs in time polynomial in
$n$, $1/\gamma$, $1/\varepsilon$, $\log(1/\delta)$, and $\log(1/\beta)$, and outputs a
nonnegative weighted graph $\widetilde{G}$ satisfying, with probability at least $1-\beta$, simultaneously
for every $S\subseteq V$,
\begin{align*}
 \left|w_G(S,V\setminus S)-w_{\widetilde{G}}(S,V\setminus S)\right|
 \leq \gamma w_G(S,V\setminus S)  + O\left(\frac{n}{\gamma\varepsilon}
 \left(\log(n/(\delta\beta\gamma\eps))\right)^{7}\right) .
\end{align*}
\end{theorem}

\begin{restatable}[Private correlation clustering]{corollary}{privatecorrelationclustering}
\label{cor:cc-intro}
For every constant $\varepsilon>0$ and $\delta=n^{-10}$, there is a
polynomial-time $(\varepsilon, \delta)$-edge-DP algorithm for unweighted complete-graph min-disagree
correlation clustering that, with high probability, outputs a partition with cost at most
\[
1.387\operatorname{OPT}_G+\widetilde O_{\varepsilon}(n).
\]
\end{restatable}

\begin{restatable}[Private Max-Cut]{corollary}{privatemaxcut}
\label{cor:maxcut-intro}
For every constant $\xi>0, \varepsilon>0$, and $\delta=n^{-10}$, there is a polynomial-time $(\varepsilon, \delta)$-edge-DP algorithm for Max-Cut that, for any non-negative weighted graph $G$, with high probability outputs a bipartition with cut value at least
\[
(0.878-\xi)\operatorname{OPT}_G-\widetilde O_{\xi,\varepsilon}(n).
\]
Here, $\operatorname{OPT}_G$ is the value of the real max-cut in $G$.
\end{restatable}

\begin{lemma}[Post-Processing]
\label{lem:post-processing}
Let $\mathcal{M} \colon \mathcal{X} \to \mathcal{Y}$ be a randomized mechanism that is $(\varepsilon, \delta)$-differentially private. Let $f \colon \mathcal{Y} \to \mathcal{Z}$ be an arbitrary randomized mapping whose internal randomness is independent of the private input data. Then the composite mechanism $f \circ \mathcal{M} \colon \mathcal{X} \to \mathcal{Z}$ remains $(\varepsilon, \delta)$-differentially private.
\end{lemma}

\begin{lemma}[Basic Adaptive Composition]
\label{lem:basic-composition}
Let $\mathcal{M}_1, \dots, \mathcal{M}_k$ be a sequence of adaptively chosen randomized mechanisms, where for each $i \in [k]$, the mechanism $\mathcal{M}_i$ is $(\varepsilon_i, \delta_i)$-differentially private. Then their adaptive composition is $\left( \sum_{i=1}^k \varepsilon_i, \sum_{i=1}^k \delta_i \right)$-differentially private.
\end{lemma}

\begin{lemma}\label{lem:chi}
For every fixed $X \in \mathcal{X}$, choose independent random vectors $Z^{(j)}\sim \mathcal{N}(0,X)$ for each $j=1,\dots,k$. Set $\overline g(u,v)=\frac1k\sum_{j=1}^k\frac{(Z_u^{(j)}-Z_v^{(j)})^2}{4},$ and $\hat g(u,v)=\min\{\overline{g}(u,v)/2,1\}$. For some universal constant $C > 0$, if
$k\geq C\log(n/(\beta_\chi\del_1))$, then with probability at least $1-\min(\beta_\chi, \del_1)$, for every pair of nodes $e=\{u,v\}$ simultaneously,
\[\frac{q_{e}(X)}{4}\leq \hat{g}(u,v)\leq q_{e}(X).\]
\end{lemma}

