\begin{lemma}[Success-Charged Composition]
\label{lem:pay-what-you-get}
Suppose that the following conditions hold for every pair of adjacent inputs $w$ and $w'$. Let $\mathcal{M}_1, \dots, \mathcal{M}_k$ be a sequence of adaptively chosen randomized mechanisms, where each mechanism outputs either a valid result or a designated failure symbol $\bottom$.
For each step $t \in [k]$ and every common transcript prefix $y_{<t} = (y_1, \dots, y_{t-1})$, let $P_t^0$ and $P_t^1$ denote the conditional output distributions of $\mathcal{M}_t(w)$ and $\mathcal{M}_t(w')$, respectively. Suppose there exist auxiliary probability measures $N_t^0$ and $N_t^1$, a privacy loss parameter $\ell_t = \ell_t(y_{<t}) \ge 0$, and global constants $\ell^* < 1/10$ and $\delta' \ge 0$ such that, for any measurable set $A$ of return values and $b \in \{0, 1\}$:
\begin{itemize}
    \item If $P_t^b(A)=0$, then $N_t^b(A)=0;$
    \item $|P_t^b(A) - N_t^b(A)| \le \delta';$
    \item $e^{-\ell_t} N_t^1(A) \le N_t^0(A) \le e^{\ell_t} N_t^1(A),$
\end{itemize}
where $\ell_t(y_{<t}) \le \ell^*$.
Furthermore, suppose there exists a deterministic bound  $L$
such that for any sequence of outputs $y_1, \dots, y_k$ sampled sequentially according to
$y_t\sim N_t^b(\cdot\mid y_{<t}),$ for $t=1,\ldots,k$,
the accumulated privacy loss over successful attempts is bounded by $L$:
\begin{equation*}
    \sum_{t=1}^k \ell_t(y_{<t}) \cdot \ind[y_t \ne \bottom] \le L.
\end{equation*}
Then, for any fixed $\delta'' \in (0,1)$, the adaptive composition $(\mathcal{M}_1, \dots, \mathcal{M}_k)$ is $(\eps, \del)$-differentially private, where
\begin{equation*}
    \eps = 4L + 4\ell^*\log(1/\del''), \qquad \del = \del'' + (1+e^{\eps})k\del'.
\end{equation*}
\end{lemma}

\begin{lemma}[Privacy of \Cref{alg:gradient_aggregation}]
\label{lem:gradient_privacy}
Fix any $\eps_{\mathrm{GE}}, \delta_{\mathrm{GE}}$ and $\beta_{\mathrm{GE}}\in(0,1)$, let $\eps_1=\frac{\eps_{\mathrm{GE}}}{320K(1+\log(2/\del_{\mathrm{GE}}))}, \del_1=\frac{\del_{\mathrm{GE}}}{20n^2K}, k=\Theta(\log\frac{n}{\beta_{\chi}\del_1}), \beta_{\chi}=\beta_{\mathrm{GE}}/4n^2K$ and $\lambda=\Theta(\frac{1}{\eps_1}\log\frac{n}{\beta_{\mathrm{GE}}\del_{\mathrm{GE}}}).$ Then each invocation of
\Cref{alg:gradient_aggregation} in \Cref{alg:main} with input $(w_i,h_i,\gamma)$ is
$(\eps_{\mathrm{GE}}, \delta_{\mathrm{GE}})$-differentially private.
\end{lemma}

\begin{lemma}[Privacy of \Cref{alg:main}]\label{lem:main-privacy}
For $0<\varepsilon\leq1$ and $0<\delta<1$, fix $\eps_2=\frac{\eps}{2T_1}$, $\eps_{\mathrm{GE}}=\frac{\eps}{4T_1\sqrt{2T_2\log(2T_1/\delta)}}$, $\delta_{\mathrm{GE}}=\frac{\delta}{2T_1T_2}.$
Then \Cref{alg:main} is
$(\eps, \del)$-differentially private.
\end{lemma}

\begin{lemma}\label{lem:sdp_error}
For every signed vector $D \in \mathbb{R}^{\binom{n}{2}}$ and every cut $S \subseteq [n]$,
\[\langle D, c_S\rangle\leq 2\max\{F(D),0\}+O(\lambda n\log n+\norm{D}_1/n).\]
Moreover, $\langle D,\one\rangle\leq2F(D)$.
\end{lemma}

\begin{lemma}\label{lem:gradient_estimation}
Let $0<\gamma<1$, $K=\Theta(\log(n/\beta_{\mathrm{GE}}))$, $\tau_1=\log(1/\beta_1)/\eps_1$ and $\beta_1=\beta_{\chi}=\beta_{\mathrm{GE}}/4n^2K$. Given nonnegative edge weights $w$ and a nonnegative partial estimate $h$, suppose $w_e\leq U$ for every $e$. Let $(g^+,g^-,r^*)=\mathsf{AggregateWitnesses}(w,h,\gamma)$ (\Cref{alg:gradient_aggregation}).
Then with probability at least $1-\beta_{\mathrm{GE}}$:
\begin{itemize}
    \item $\langle h,g^+\rangle\geq(1+\gamma)\langle w,g^+\rangle;$
    \item $\langle h,g^-\rangle\leq(1-\gamma)\langle w,g^-\rangle;$
    \item For every cut $S$ simultaneously, \[(1-\gamma)\langle w,c_S\odotc r^*\rangle-B\leq \langle h,c_S\odotc r^*\rangle\leq(1+\gamma)\langle w,c_S\odotc r^*\rangle+B,\]
where $B=\Theta\left(\tau_1+\lambda n\log n+nU\right).$
\end{itemize}
\end{lemma}

\begin{lemma}\label{lem:outer_round}
With probability at least $1-T_1T_2\beta_{\mathrm{GE}}-T_1\beta_2$, \Cref{alg:main} terminates with $a_i=0$ or $\widetilde{M}_i\leq M_{\mathsf{stop}}$ in at most $T_1 = O(\log(nU))$ outer rounds.
\end{lemma}

\begin{lemma}\label{lem:utility}
Let $n\geq2$, $U\geq1$, $0<\gamma\leq1/4$, $0<\eps\leq1$, and $0<\delta,\beta<1/10$.
Choose all parameters as in \Cref{alg:main}, in particular
$\eps_{\mathrm{GE}}=\eps/(4T_1\sqrt{2T_2\log(2T_1/\delta)})$,
$\delta_{\mathrm{GE}}=\delta/(2T_1T_2)$, and $M_{\mathrm{stop}}=C(nU\log\frac{nU}{\delta\beta\gamma\eps}+\frac{n}{\gamma\varepsilon}(\log\frac{nU}{\delta\beta\gamma\eps})^6)
\geq10(B+\tau_2/\gamma)$, for a sufficiently large universal constant $C$.
Given a nonnegative weighted $n$-vertex graph $G$ with edge weights bounded by $U$, \Cref{alg:main} outputs a
nonnegative weighted graph $\widetilde{G}$ satisfying,
with probability at least $1-\beta$, simultaneously
for every $S\subseteq V$,
\begin{align*}
 \left|w_G(S,V\setminus S)-w_{\widetilde{G}}(S,V\setminus S)\right|
 \leq \gamma w_G(S,V\setminus S)  + O\left(nU\log\frac{nU}{\delta\beta\gamma\eps}+\frac{n}{\gamma\varepsilon}
 \left(\log\frac{nU}{\delta\beta\gamma\eps}\right)^7\right).
\end{align*}
\end{lemma}

\begin{lemma}[Chi-squared Tail Bound~\cite{laurent2000adaptive}]\label{lem:chi_square_tail}
Let $Y_1, \dots, Y_k$ be independent standard normal random variables, i.e., $Y_i \sim \mathcal{N}(0, 1)$. The random variable $Q = \sum_{i=1}^k Y_i^2$ follows a Chi-squared distribution with $k$ degrees of freedom, denoted as $Q \sim \chi_k^2$. For any such $Q$, there exists a universal constant $c > 0$ such that
\[
 \Prb\left[\frac{Q}{k} \notin \left[\frac{1}{2}, 2\right]\right] \leq 2e^{-ck}.
\]
\end{lemma}

\begin{lemma}[Capped unit-bounded cut release]\label{lem:capped-unit-release}
Let $D\subseteq\binom V2$ be public and let $x\in[0,1]^D$. For $0<\gamma\leq1/4$, $0<\varepsilon\leq1$, and $0<\delta,\beta_{\rm cap}<1/10$, there is a polynomial-time $(\varepsilon, \delta)$-DP mechanism under adjacency defined in Definition~\ref{def:DP} on $x$ that outputs $q\in[0,1]^D$ such that, except with probability $\beta_{\rm cap}$, simultaneously for every $S\subseteq V$,
\begin{equation*}
 \left|q(\delta_D(S))-x(\delta_D(S))\right| \leq \gamma x(\delta_D(S))+A_{\rm cap},
\end{equation*}
where
\[
 A_{\rm cap} \leq O\left(\frac{n}{\gamma\varepsilon}
 \left(\log\frac{n}{\delta\beta_{\rm cap}\gamma\varepsilon}\right)^7\right).
\]
\end{lemma}

