\begin{algorithm}[h!]
\caption{$\mathsf{FindWitness}(D,r)$}
\label{alg:gradient_estimation}
\begin{algorithmic}[1]
\REQUIRE A signed objective vector $D$, a mask $r$, privacy parameters $\epsilon_{\mathrm{GE}}, \delta_{\mathrm{GE}} \in (0, 1)$, and a failure probability $\beta_{\mathrm{GE}}$.
\ENSURE A witness $g$ or the failure symbol $\bot$.
\STATE Set parameters: $k=\Theta(\log(\frac{n}{\beta_\chi\del_1}))$, $K=\Theta(\log(\frac{n}{\beta_{\mathrm{GE}}}))$, $\lambda=\Theta(\frac{1}{\eps_1}\log\frac{n}{\beta_{\mathrm{GE}}\del_{\mathrm{GE}}})$,  $\eps_1=\frac{\eps_{\mathrm{GE}}}{320K(1+\log(2/\del_{\mathrm{GE}}))}$, $\del_1=\frac{\del_{\mathrm{GE}}}{20n^2K}$, $\tau_1=\frac{\log(1/\beta_1)}{\eps_1}$, $\beta_1=\beta_{\chi}=\frac{\beta_{\mathrm{GE}}}{4n^2K}$.
\IF{$r=0$}
  \STATE \Return $\bot$
\ENDIF
\STATE Compute the optimizer $X_D$ of \eqref{eq:F_D}.\label{line:optimize_XD}
\FOR{$i=1,\dots,K$}
    \STATE Choose random vectors $Z^{(j)}\sim \mathcal{N}(0,X_D)$ for each $j=1,\dots,k$.
    \STATE Set $\overline g(u,v)=\frac1k\sum_{j=1}^k\frac{(Z_u^{(j)}-Z_v^{(j)})^2}{4},$ and $\hat g(u,v)=\min\{\overline{g}(u,v)/2,1\}$.
    \STATE Compute a private estimate $Y=\langle D, \hat{g} \rangle+L$, where $L\sim\Lap(1/\eps_{1})$.                               
  \STATE Set $\hat g_{\max}\gets\max\{\hat g(e):r(e)>0\}$.
    \IF{$Y<\tau_1$ or $\hat g_{\max}=0$} \label{line:accepted_trial}
    \STATE \textbf{Continue.}
  \ENDIF
  \STATE Set $g(e)\gets r(e)\cdot\hat g(e)/\hat g_{\max}$ for each $e$. \label{line:rescale_gradient}
  \RETURN $g$.
\ENDFOR
\STATE \Return $\bot$.
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[ht]
\caption{$\mathsf{AggregateWitnesses}(w,h,\gamma)$}
\label{alg:gradient_aggregation}
\begin{algorithmic}[1]
\STATE $(g^+,g^-,r)\gets(0,0,\one_{\binom{n}{2}})$.
\LOOP
  \IF{$r=0$}
    \STATE Return $\{g^+,g^-,0\}$.
  \ENDIF
  \STATE Let $g_{\mathrm{new}}=\mathsf{FindWitness}(D^+,r)$ where $D^+=r\odotc(h-(1+\gamma)w)$.
  \IF{$g_{\mathrm{new}}\ne \bot$}
    \STATE $g^+\gets g^++g_{\mathrm{new}}$, $r\gets r-g_{\mathrm{new}}$ and \textbf{continue}.\label{line:aggregate-positive}
  \ENDIF
  \STATE Let $g_{\mathrm{new}}=\mathsf{FindWitness}(D^-,r)$ where $
 D^-=r\odotc((1-\gamma)w-h).$
  \IF{$g_{\mathrm{new}}\ne \bot$}
    \STATE $g^-\gets g^-+g_{\mathrm{new}}$, $r\gets r-g_{\mathrm{new}}$ and \textbf{continue}.\label{line:aggregate-negative}
  \ENDIF
\STATE Release $\{g^+,g^-,r\}$  
\STATE Return $\{g^+,g^-,r\}$  
\ENDLOOP
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[h!]
\caption{$\mathsf{ClipEdgeWeights}(w)$}
\label{alg:preprocess}
\begin{algorithmic}[1]
\REQUIRE A weight vector $w \in \mathbb{R}_{\ge 0}^{\binom{n}{2}}$, a relative error tolerance $\gamma \in (0, 1)$, a privacy parameter $\eps_0 \in (0, 1)$, and a failure probability $\beta_0 \in (0, 1)$.
\ENSURE A bounded edge-weight vector $w'$ and a publicly released private estimate $Y$ of the excess weights.
\STATE Set the bounding threshold $U = \frac{8}{\eps_0\gamma}\log\left(\frac{n}{\beta_0}\right)$ and the noise shift $V = \frac{2}{\eps_0}\log\left(\frac{n}{\beta_0}\right)$.
\FOR{each edge $e \in \binom{n}{2}$}
  \STATE Decompose weights: $v_e \gets (w_e-U)_+$ and $w'_e \gets \min\{w_e, U\}$.
  \STATE Draw Laplace noise: $L_e \sim \Lap(1/\eps_0)$.
  \STATE Compute private excess: $Y_e \gets \max\left\{0, v_e + L_e - V \right\}$.
\ENDFOR
\RETURN $(w', Y)$.
\end{algorithmic}
\end{algorithm}
